function safeRedirectTarget(target) {
  // BUG: only checks for a leading '/', so '//evil.com' and '/\\evil.com'
  // (which browsers treat as absolute) are trusted -> open redirect.
  if (target && target.startsWith('/')) {
    return target;
  }
  return '/';
}

module.exports = { safeRedirectTarget };

test_setup_files.behavior_test.js:
const assert = require('node:assert');
const { safeRedirectTarget } = require('./redirect.js');

// safe same-site paths pass through
assert.strictEqual(safeRedirectTarget('/dashboard'), '/dashboard');
assert.strictEqual(safeRedirectTarget('/a/b?x=1'), '/a/b?x=1');

// off-site tricks are rejected
assert.strictEqual(safeRedirectTarget('//evil.com'), '/', 'protocol-relative //host not blocked');
assert.strictEqual(safeRedirectTarget('/\\evil.com'), '/', 'backslash /\\host not blocked');
assert.strictEqual(safeRedirectTarget('https://evil.com'), '/');

// junk / empty defaults to '/'
assert.strictEqual(safeRedirectTarget(''), '/');
assert.strictEqual(safeRedirectTarget(undefined), '/');
assert.strictEqual(safeRedirectTarget('relative'), '/');

console.log('ok');

reference_solution.redirect.js:
function safeRedirectTarget(target) {
  if (typeof target !== 'string' || target.length === 0) {
    return '/';
  }
  if (!target.startsWith('/')) {
    return '/';
  }
  if (target.startsWith('//') || target.startsWith('/\\')) {
    return '/';
  }
  return target;
}

module.exports = { safeRedirectTarget };

