function safeRedirectTarget(target) {
  // INCOMPLETE FIX: blocks '//host' but misses the '/\\host' backslash variant.
  if (typeof target !== 'string' || !target.startsWith('/')) {
    return '/';
  }
  if (target.startsWith('//')) {
    return '/';
  }
  return target;
}

module.exports = { safeRedirectTarget };
